contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount == 10);
        require(address(this).balance >= amount);
        // sanity: this contract deployed c, so it is the bank
        require(c.bank() == address(this));
        uint potBefore = c.pot(); if (__ESBMC_reverted()) return;
        uint combinedBefore = address(this).balance + address(c).balance;
        c.play{value: amount}(); if (__ESBMC_reverted()) return;
        uint potAfter = c.pot(); if (__ESBMC_reverted()) return;
        uint combinedAfter = address(this).balance + address(c).balance;
        // winning play: fee returns to bank (= this contract) and payout goes to
        // this contract, so no value leaves the (player + contract) system;
        // losing play: the 10 wei just sits in the pot. Either way, conserved.
        assert(combinedAfter == combinedBefore);
    }
    receive() external payable {}
}

